def test_get_environment_proxies():
    from unittest.mock import patch, MagicMock
    solution = Solution()

    # Mock getproxies to return a dictionary with http and https proxies, and no_proxy without '*'
    proxy_info = {
        "http": "http://proxy1.example.com",
        "https": "https://proxy2.example.com",
        "no": "example.com,google.com"
    }

    with patch('urllib.request.getproxies', return_value=proxy_info):
        assert solution.get_environment_proxies() == {
            "http://": "http://proxy1.example.com",
            "https://": "https://proxy2.example.com",
            "all://*example.com": None,
            "all://*google.com": None
        }

