class TestGetWeekdayIndex(unittest.TestCase):

    @patch('your_module.WEEKDAYS', ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"])
    def test_get_weekday_index_valid_weekday(self, mock_weekdays):
        solution = Solution()
